                terminal_command: Some(
                    "/bin/panopt _viewer --slot vt1 --port 7600".to_string(),
                ),
                ..Default::default()
            },
        ],
    );
    sidebar.ingest_panes(PaneManifest { panes });
    assert_eq!(sidebar.slot_pane, Some(PaneId::Terminal(7)));
}

