#[test]
fn visible_content_count_excludes_suppressed_panes() {
    use std::collections::HashMap;
    // A visible agent in front of the suppressed boot viewer. The whole-
    // session count (which gates the deliberate close) sees both; the
    // visible count (which the floor must keep above zero) sees only the
    // agent - a hidden pane does nothing to stop the sidebar expanding.
    let mut panes = HashMap::new();
    panes.insert(
        0usize,
        vec![
            PaneInfo {
                id: 3,
                is_selectable: true,
                is_suppressed: true,
                terminal_command: Some(
                    "/bin/panopt _viewer --slot main --port 7600".to_string(),
                ),
                ..Default::default()
            },
            PaneInfo {
                id: 9,
                is_selectable: true,
                terminal_command: Some("/bin/panopt _agent --id a".to_string()),
                ..Default::default()
            },
        ],
    );
    let mut sidebar = pane_with(Mode::Todos);
    sidebar.ingest_panes(PaneManifest { panes });
    assert_eq!(sidebar.content_pane_count(), 2);
    assert_eq!(sidebar.visible_content_pane_count(), 1);
}

