#[test]
fn exited_husk_counts_as_occupying_the_right() {
    use std::collections::HashMap;
    // `/q` in an agent pane exits its command, but the `_agent` command
    // pane does not close - it lingers drawn, showing the exit status,
    // still holding its tile so the sidebar stays put. The floor must treat
    // that husk as occupying the right (count it), or it resurfaces the
    // suppressed boot viewer beside the husk - the spurious "new pane" bug.
    let mut panes = HashMap::new();
    panes.insert(
        0usize,
        vec![
            PaneInfo {
                id: 9,
                is_selectable: true,
                exited: true,
                terminal_command: Some("/bin/panopt _agent --id a".to_string()),
                ..Default::default()
            },
            PaneInfo {
                id: 3,
                is_selectable: true,
                is_suppressed: true,
                terminal_command: Some(
                    "/bin/panopt _viewer --slot main --port 7600".to_string(),
                ),
                ..Default::default()
            },
        ],
    );
    let mut sidebar = pane_with(Mode::Todos);
    sidebar.ingest_panes(PaneManifest { panes });
    // The husk is excluded from the deliberate-close count (it is gone as
    // far as swappable content goes)...
    assert_eq!(sidebar.content_pane_count(), 1);
    // ...but it is still drawn, so the floor sees the right side occupied
    // and does not resurface a second pane.
    assert_eq!(sidebar.visible_content_pane_count(), 1);
}

