/// Count the content panes currently *drawn* on the right - the ones whose
/// tiles keep the sidebar from expanding to full width. A pane is drawn iff
/// it is neither floating (an overlay, not the content slot) nor suppressed
/// (running but hidden behind a swapped-in pane). Crucially this *includes*
/// exited panes: a `panopt _agent`/`_viewer` is a Zellij command pane, and
/// when its command exits the pane does not close - it lingers showing the
/// exit status, still occupying its tile. Counting an exited husk as gone
/// makes [`Self::ensure_content_floor`] resurface a second pane *beside* the
/// husk, when the right side was never actually empty. This is the count
/// the floor must keep above zero, and it is deliberately distinct from
/// `content_pane_count` (which excludes exited panes but counts suppressed
/// ones, because a hidden-but-swappable pane is still a reason to refuse a
/// *deliberate* `x`/`Ctrl-q` close).
fn visible_content_pane_count(&self) -> usize {
    self.panes
        .iter()
        .filter(|p| !p.floating && !p.suppressed)
        .count()
}

/// The first suppressed-but-running pane the floor can resurface, a viewer
/// preferred over an agent/terminal since a viewer is the cockpit's natural
/// content slot. The usual occupant is the boot `--slot main` viewer, which
/// `show_in_slot` suppressed when an agent was swapped in front of it; if
/// that agent is then closed, this is what we bring back. `None` when the
/// session has no hidden content to restore at all.
fn first_suppressed_content_pane(&self) -> Option<PaneId> {
    self.first_suppressed_viewer().or_else(|| {
        self.panes
            .iter()
            .find(|p| p.suppressed && !p.exited && !p.floating)
            .map(|p| p.id)
    })
}

/// Keep at least one content pane visible on the right - the safety net the
/// keybind close gate and the viewer's in-pane gate can't be: a content
/// pane can vanish by a path neither sees - an agent or shell exiting, a
/// Ctrl-c the inner program consumes, a crash, or a swap that suppressed the
/// boot viewer behind a pane the user then closed. Any of these drops the
/// *visible* content count to zero, at which point Zellij re-tiles and the
/// five sidebar plugins expand to fill the screen with no obvious way back.
///
/// Unlike the file-based viewer gate (#96), this reads only this instance's
/// own live manifest, so it is correct even if a stale `content-count` file
/// from another cockpit session on the same project is misleading. When no
/// content pane is visible, re-show a suppressed one if the session still
/// has it running (the common case), else spawn a fresh blank viewer.
/// Gatekeeper-only, like the other session-wide projections, so the five
/// instances don't all react to the same manifest.
fn ensure_content_floor(&mut self) {
    if self.mode != Mode::Todos || !self.permitted {
        return;
    }
    if self.visible_content_pane_count() > 0 {
        self.has_had_content = true;
        return;
    }
    // A zero count before we have ever seen content is the cockpit still
    // booting the layout's viewer, not a drop - restoring here would race
    // a duplicate blank pane in front of the real one. Wait for it.
    if !self.has_had_content {
        return;
    }
    match self.first_suppressed_content_pane() {
        Some(pane) => show_pane_with_id(pane, false, false),
        None => self.spawn_blank_viewer(),
    }
}

