#[test]
fn visible_content_count_excludes_suppressed_panes() {
    use std::collections::HashMap;
    // A visible agent in front of the suppressed boot viewer. The whole-
    // session count (which gates the deliberate close) sees both; the
    // visible count (which the floor must keep above zero) sees only the
    // agent - a hidden pane does nothing to stop the sidebar expanding.
    let mut panes = HashMap::new();
    panes.insert(
        0usize,
        vec![
            PaneInfo {
                id: 3,
                is_selectable: true,
                is_suppressed: true,
                terminal_command: Some(
                    "/bin/panopt _viewer --slot main --port 7600".to_string(),
                ),
                ..Default::default()
            },
            PaneInfo {
                id: 9,
                is_selectable: true,
                terminal_command: Some("/bin/panopt _agent --id a".to_string()),
                ..Default::default()
            },
        ],
    );
    let mut sidebar = pane_with(Mode::Todos);
    sidebar.ingest_panes(PaneManifest { panes });
    assert_eq!(sidebar.content_pane_count(), 2);
    assert_eq!(sidebar.visible_content_pane_count(), 1);
}

#[test]
fn exited_husk_counts_as_occupying_the_right() {
    use std::collections::HashMap;
    // `/q` in an agent pane exits its command, but the `_agent` command
    // pane does not close - it lingers drawn, showing the exit status,
    // still holding its tile so the sidebar stays put. The floor must treat
    // that husk as occupying the right (count it), or it resurfaces the
    // suppressed boot viewer beside the husk - the spurious "new pane" bug.
    let mut panes = HashMap::new();
    panes.insert(
        0usize,
        vec![
            PaneInfo {
                id: 9,
                is_selectable: true,
                exited: true,
                terminal_command: Some("/bin/panopt _agent --id a".to_string()),
                ..Default::default()
            },
            PaneInfo {
                id: 3,
                is_selectable: true,
                is_suppressed: true,
                terminal_command: Some(
                    "/bin/panopt _viewer --slot main --port 7600".to_string(),
                ),
                ..Default::default()
            },
        ],
    );
    let mut sidebar = pane_with(Mode::Todos);
    sidebar.ingest_panes(PaneManifest { panes });
    // The husk is excluded from the deliberate-close count (it is gone as
    // far as swappable content goes)...
    assert_eq!(sidebar.content_pane_count(), 1);
    // ...but it is still drawn, so the floor sees the right side occupied
    // and does not resurface a second pane.
    assert_eq!(sidebar.visible_content_pane_count(), 1);
}

#[test]
fn floor_prefers_a_suppressed_viewer_to_resurface() {
    use std::collections::HashMap;
    // Both content panes are suppressed (the agent the user just closed
    // had been swapped in front of the boot viewer; closing it left both
    // hidden). With nothing visible the floor must resurface one - and it
    // picks the viewer, the cockpit's natural empty content slot, over the
    // agent.
    let mut panes = HashMap::new();
    panes.insert(
        0usize,
        vec![
            PaneInfo {
                id: 4,
                is_selectable: true,
                is_suppressed: true,
                terminal_command: Some("/bin/panopt _agent --id a".to_string()),
                ..Default::default()
            },
            PaneInfo {
                id: 7,
                is_selectable: true,
                is_suppressed: true,
                terminal_command: Some(
                    "/bin/panopt _viewer --slot main --port 7600".to_string(),
                ),
                ..Default::default()
            },
        ],
    );
    let mut sidebar = pane_with(Mode::Todos);
    sidebar.ingest_panes(PaneManifest { panes });
    assert_eq!(sidebar.visible_content_pane_count(), 0);
    assert_eq!(
        sidebar.first_suppressed_content_pane(),
        Some(PaneId::Terminal(7))
    );
}

